class Solution {
public:
    int numberOfMatches(int n) {
        int total_team = n;
        int total_match = 0;
        while(total_team!=1){
            if(total_team % 2 == 0){
                total_match = total_match + (total_team/2);
                total_team = total_team/2;
            }else{
                total_match = total_match + ((total_team-1)/2);
                total_team = ((total_team-1)/2) + 1;
            }
        }
        return total_match;
    }
};

